window.CARDS=window.CARDS||{};CARDS["people-utomiya-riku"]=[{"i":"sc-utomiya-riku-y2v1-p268-1","v":"y2v1","y":2,"o":16,"k":"","w":"tsubaki-sakurako ayanokouji-kiyotaka utomiya-riku","q":"utomiya riku ch 5  seeking a partner approaches ayanokoji at keyaki mall with tsubaki  explains tsubaki hasn t found a partner  leaves with tsubaki  searches with her  approaches him","h":"<article class=\"card\" id=\"sc-utomiya-riku-y2v1-p268-1\"><h3><span class=\"ttl\">Ch.5: Seeking a partner<\/span><span class=\"meta\">Y2V1 · p.268–275<\/span><\/h3><p class=\"setup\">Approaches Ayanokōji at Keyaki Mall with Tsubaki. Explains Tsubaki hasn’t found a partner. Leaves with Tsubaki.<\/p><p class=\"with\">with <a href=\"tsubaki-sakurako.html\">Tsubaki Sakurako<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsubaki Sakurako<\/b> Searches with her.<span class=\"pg\">p.268–275<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Approaches him.<span class=\"pg\">p.268–275<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-utomiya-riku-y2v1-p268-2\">→ After: Epilogue: Seeking a partner<\/button><\/div><\/article>"},{"i":"sc-utomiya-riku-y2v1-p268-2","v":"y2v1","y":2,"o":16,"k":"","w":"tsubaki-sakurako ayanokouji-kiyotaka utomiya-riku","q":"utomiya riku epilogue  seeking a partner approaches ayanokoji at keyaki mall  leaves with tsubaki  searches with her  approaches him","h":"<article class=\"card\" id=\"sc-utomiya-riku-y2v1-p268-2\"><h3><span class=\"ttl\">Epilogue: Seeking a partner<\/span><span class=\"meta\">Y2V1 · p.268–275<\/span><\/h3><p class=\"setup\">Approaches Ayanokōji at Keyaki Mall. Leaves with Tsubaki.<\/p><p class=\"with\">with <a href=\"tsubaki-sakurako.html\">Tsubaki Sakurako<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsubaki Sakurako<\/b> Searches with her.<span class=\"pg\">p.268–275<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Approaches him.<span class=\"pg\">p.268–275<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-utomiya-riku-y2v1-p268-1\">← Before: Ch.5: Seeking a partner<\/button><\/div><\/article>"},{"i":"sc-utomiya-riku-y2v2-p221-1","v":"y2v2","y":2,"o":17,"k":"spoken","w":"yagami-takuya takahashi-osamu housen-kazuomi hatano utomiya-riku","q":"utomiya riku the representatives  gathering he shows up at the empty first year classroom  sent by his classmates who avoid troublesome matters   looks like only you re here now  yagami   although i don t think i m the type to be a leader  i came because the other students didn t want to come  while students in my class speak their minds freely in general  they don t have much taste for these troublesome matters   we ve recently lost a comrade  honestly  it s quite a heavy loss   he had once said to me that he wanted us to join the student council together and create a livelier environment for everyone in this school   do you think hosen will come   50 50  you seem to trust housen quite a bit  i bet he won t come at all   if he thinks he can simply force us to hand over our private points like that  he is too arrogant  if we can smoothly form the groups with all four classes this time  it would be meaningful  since we are facing the 2nd and 3rd years  we should cooperate  nevertheless  housen refused our offer   i understand that this is his strategy  however  it stands no chance of winning   we were told that this uninhabited island exam would also test skills other than academic ability  while class d is last place in terms of academic ability  their physical abilities are second in our year and only by a narrow margin to being the first  as a result  they might play an important role in the formation of optimal groups    housen arrives  the hatano accusation  the near fight  he grabs housen s arm   housen  don t bring your violent tendencies here   if it s necessary   unfortunately  i m not as kind as takahashi   do you think of violence as a game   how boring  but  if that s what you want  you don t have to wait until next time  i can take on the fight now  however  that is only if you promise not to attack any more of my classmates   i suspect that you re the one who got hatano expelled  he s not the kind of student who would easily break the school rules   i remember clearly the look on his face when he got expelled  he had been tricked by someone   who else could it possibly be  the negotiation closes  strongest four  two from class d  his reluctance yields to yagami   the benefits of cooperating with the other classes are too small  it s pointless  we re just giving up on class points   losing class points won t be our only concern if we end up becoming food for the upperclassmen   if we go with that strategy then we won t be able to make any difference to our current class standings    what are you trying to do  housen   but what if we can t form big groups at will   you ve got to be kidding  housen   you bastard   you re just going to give all the benefits to class d like this   if we let him take advantage of us now  he ll be sure to do it again   that   housen  no more demands  okay    i understand  cold  precise  willing to stand in front of a fist  his grief over hatano is the fuel  he yields only to coalition logic  they co chair the gathering  they disagree on class d  the peacekeeper between him and housen  he accuses  nearly fights  and swallows his pride for the pact  his class 1 c comrade  expelled  he suspects housen","h":"<article class=\"card\" id=\"sc-utomiya-riku-y2v2-p221-1\"><h3><span class=\"ttl\">The representatives&#x27; gathering<\/span><span class=\"meta\">Y2V2 · p.221–235<\/span><\/h3><p class=\"setup\">He shows up at the empty first-year classroom, sent by his classmates who avoid troublesome matters. Housen arrives; the Hatano accusation; the near-fight; he grabs Housen&#x27;s arm. The negotiation closes: strongest four, two from Class D; his reluctance yields to Yagami.<\/p><p class=\"with\">with <a href=\"yagami-takuya.html\">Yagami Takuya<\/a> · <a href=\"takahashi-osamu.html\">Takahashi Osamu<\/a> · <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"index.html#hatano\">Hatano<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Looks like only you’re here now, Yagami.”<span class=\"pg\">p.221<\/span><\/li><li class=\"q spoken\">“Although I don’t think I’m the type to be a leader, I came because the other students didn’t want to come. While students in my class speak their minds freely in general, they don’t have much taste for these troublesome matters.”<span class=\"pg\">p.221<\/span><\/li><li class=\"q spoken\">“We’ve recently lost a comrade. Honestly, it’s quite a heavy loss.”<span class=\"pg\">p.222<\/span><\/li><\/ul><details class=\"more\"><summary>31 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “He had once said to me that he wanted us to join the student council together and create a livelier environment for everyone in this school.”<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you think Hosen will come?”<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “50/50? You seem to trust Housen quite a bit. I bet he won’t come at all.”<span class=\"pg\">p.223<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If he thinks he can simply force us to hand over our private points like that, he is too arrogant. If we can smoothly form the groups with all four classes this time, it would be meaningful. Since we are facing the 2nd and 3rd years, we should cooperate. Nevertheless, Housen refused our offer.”<span class=\"pg\">p.223<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I understand that this is his strategy. However, it stands no chance of winning.”<span class=\"pg\">p.223<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We were told that this uninhabited island exam would also test skills other than academic ability. While Class D is last place in terms of academic ability, their physical abilities are second in our year and only by a narrow margin to being the first. As a result, they might play an important role in the formation of optimal groups. ”<span class=\"pg\">p.224<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Housen, don’t bring your violent tendencies here.”<span class=\"pg\">p.225<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If it’s necessary.”<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Unfortunately, I’m not as kind as Takahashi.”<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you think of violence as a game?”<span class=\"pg\">p.227<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How boring, but, if that’s what you want, you don’t have to wait until next time. I can take on the fight now. However, that is only if you promise not to attack any more of my classmates.”<span class=\"pg\">p.227<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I suspect that you’re the one who got Hatano expelled. He’s not the kind of student who would easily break the school rules.”<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I remember clearly the look on his face when he got expelled. He had been tricked by someone.”<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Who else could it possibly be?”<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The benefits of cooperating with the other classes are too small. It’s pointless. We’re just giving up on Class Points.”<span class=\"pg\">p.231<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Losing Class Points won’t be our only concern if we end up becoming food for the upperclassmen.”<span class=\"pg\">p.231<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If we go with that strategy then we won’t be able to make any difference to our current class standings.”<span class=\"pg\">p.231<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “… What are you trying to do? Housen.”<span class=\"pg\">p.233<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But what if we can’t form big groups at will?”<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’ve got to be kidding, Housen.”<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You bastard…”<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re just going to give all the benefits to Class D like this?”<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If we let him take advantage of us now, he’ll be sure to do it again.”<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That…”<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Housen, no more demands. Okay?”<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “… I understand.”<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Cold, precise, willing to stand in front of a fist; his grief over Hatano is the fuel; he yields only to coalition logic.<span class=\"pg\">p.221–235<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> They co-chair the gathering; they disagree on Class D.<span class=\"pg\">p.221–235<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Takahashi Osamu<\/b> The peacekeeper between him and Housen.<span class=\"pg\">p.225–235<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> He accuses, nearly fights, and swallows his pride for the pact.<span class=\"pg\">p.225–235<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hatano<\/b> His Class 1-C comrade, expelled (he suspects Housen).<span class=\"pg\">p.222–235<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-utomiya-riku-y2v2-p254-1\">→ After: Coverage note: passing mentions<\/button><\/div><\/article>"},{"i":"sc-utomiya-riku-y2v2-p254-1","v":"y2v2","y":2,"o":17,"k":"","w":"utomiya-riku","q":"utomiya riku coverage note  passing mentions  utomiya riku kun from class c    the yagami summon list   utomiya and i were the only participants from our classes  we were allowed to tell one person in our classes about it to make it fair  but i didn t tell anyone  utomiya might have told someone though","h":"<article class=\"card\" id=\"sc-utomiya-riku-y2v2-p254-1\"><h3><span class=\"ttl\">Coverage note: passing mentions<\/span><span class=\"meta\">Y2V2 · p.254–255<\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Utomiya Riku-kun from Class C” — the Yagami summon list.<span class=\"pg\">p.254<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Utomiya and I were the only participants from our classes, we were allowed to tell one person in our classes about it to make it fair, but I didn’t tell anyone. Utomiya might have told someone though.”<span class=\"pg\">p.255<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-utomiya-riku-y2v2-p221-1\">← Before: The representatives&#x27; gathering<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-utomiya-riku-y2v2-p264-1\">→ After: The Hōsen plan<\/button><\/div><\/article>"},{"i":"sc-utomiya-riku-y2v2-p264-1","v":"y2v2","y":2,"o":17,"k":"spoken","w":"ayanokouji-kiyotaka tsubaki-sakurako housen-kazuomi utomiya-riku","q":"utomiya riku the hosen plan he shows up at the convenience store when ayanokoji is about to meet keisei   sorry  for having to talk to you like this   it s about housen kazuomi   ayanokouji senpai  in the april special exam  you teamed up with housen   we want to take housen by surprise on the uninhabited island exam   housen doesn t have many private points right now  in other words  if he withdraws from the exam  even as a first year student who gets a lighter penalty  he won t be able to pay for his relief   are you trying to force housen out of the school   in class c  a boy named hatano was expelled from the school  i think housen had something to do with it   of course  i d be lying if i said i didn t hate him  nonetheless  what s most important is to prevent another unprepared person from being expelled   yes  thanks to him  our class lost 100 points   housen hasn t formed any alliances with people outside his class  however  he has formed a partnership with you  ayanokouji senpai   please lend me your hand   then  could you keep this in mind  we re willing to pay you a large sum of points if you re able to get housen expelled from this school   that   we can t answer that   i apologize for that  we ve already given up on the bounty   if we get you expelled  news of that ll spread throughout the school  we ll be enemies with the 2nd year class d  them hating the people who got their       classmate expelled is to be expected   no  the reason for that is because all the class 1 d students are afraid of housen  rather  there re a lot of students who wish that he be expelled   anyway  remember  please remember this  the only thing we care about is defeating housen  he wants him on board against housen  his classmate  the lollipop  she helps  the target","h":"<article class=\"card\" id=\"sc-utomiya-riku-y2v2-p264-1\"><h3><span class=\"ttl\">The Hōsen plan<\/span><span class=\"meta\">Y2V2 · p.264–270<\/span><\/h3><p class=\"setup\">He shows up at the convenience store when Ayanokōji is about to meet Keisei.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"tsubaki-sakurako.html\">Tsubaki Sakurako<\/a> · <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Sorry. For having to talk to you like this.”<span class=\"pg\">p.265<\/span><\/li><li class=\"q spoken\">“It’s about Housen Kazuomi.”<span class=\"pg\">p.266<\/span><\/li><li class=\"q spoken\">“Ayanokouji-senpai. In the April special exam, you teamed up with Housen.”<span class=\"pg\">p.266<\/span><\/li><\/ul><details class=\"more\"><summary>18 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “We want to take Housen by surprise on the uninhabited island exam.”<span class=\"pg\">p.266<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Housen doesn’t have many private points right now. In other words, if he withdraws from the exam. Even as a first year student who gets a lighter penalty, he won’t be able to pay for his relief.”<span class=\"pg\">p.267<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you trying to force Housen out of the school?”<span class=\"pg\">p.267<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In Class C, a boy named Hatano was expelled from the school. I think Housen had something to do with it.”<span class=\"pg\">p.267<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Of course, I’d be lying if I said I didn’t hate him. Nonetheless, what’s most important is to prevent another unprepared person from being expelled.”<span class=\"pg\">p.267<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes. Thanks to him, our class lost 100 points.”<span class=\"pg\">p.267<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Housen hasn’t formed any alliances with people outside his class. However, he has formed a partnership with you, Ayanokouji-senpai.”<span class=\"pg\">p.268<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Please lend me your hand.”<span class=\"pg\">p.268<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then, could you keep this in mind? We’re willing to pay you a large sum of points if you’re able to get Housen expelled from this school.”<span class=\"pg\">p.268<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That.”<span class=\"pg\">p.268<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We can’t answer that.”<span class=\"pg\">p.269<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I apologize for that. We’ve already given up on the bounty.”<span class=\"pg\">p.269<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If we get you expelled, news of that’ll spread throughout the school. We’ll be enemies with the 2nd year Class D. Them hating the people who got their …  …  classmate expelled is to be expected.”<span class=\"pg\">p.270<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No. The reason for that is because all the Class 1-D students are afraid of Housen. Rather, there’re a lot of students who wish that he be expelled.”<span class=\"pg\">p.270<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Anyway, remember. Please remember this. The only thing we care about is defeating Housen.”<span class=\"pg\">p.270<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> He wants him on board against Housen.<span class=\"pg\">p.264–270<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsubaki Sakurako<\/b> His classmate; the lollipop; she helps.<span class=\"pg\">p.264–270<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> The target.<span class=\"pg\">p.264–270<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-utomiya-riku-y2v2-p254-1\">← Before: Coverage note: passing mentions<\/button><\/div><\/article>"},{"i":"sc-utomiya-riku-y2v3-p267-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"tsubaki-sakurako yagami-takuya utomiya-riku","q":"utomiya riku utomiya enforces tsubaki s will on yagami  sorry yagami  i don t have anything against you  but  it can t be helped   either you come clean and tell us what you know  or you retire right here  right now   yer nearing your limit  yagami kun  acts as tsubaki s enforcer   restrains yagami in a full nelson then a headlock  apologizing but not relenting  threatening to retire him or extract kushida s secrets directly  his control of class 1 c is revealed to be a front for tsubaki s manipulations  carries out her coercion    using utomiya as a medium  physically interrogates him","h":"<article class=\"card\" id=\"sc-utomiya-riku-y2v3-p267-1\"><h3><span class=\"ttl\">Utomiya enforces Tsubaki&#x27;s will on Yagami<\/span><span class=\"meta\">Y2V3 · p.267–273<\/span><\/h3><p class=\"with\">with <a href=\"tsubaki-sakurako.html\">Tsubaki Sakurako<\/a> · <a href=\"yagami-takuya.html\">Yagami Takuya<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Sorry Yagami. I don&#x27;t have anything against you, but… it can&#x27;t be helped.&quot;<span class=\"pg\">p.272<\/span><\/li><li class=\"q spoken\">&quot;Either you come clean and tell us what you know, or you retire right here, right now.&quot;<span class=\"pg\">p.272<\/span><\/li><li class=\"q spoken\">&quot;Yer nearing your limit, Yagami-kun.&quot;<span class=\"pg\">p.273<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Acts as Tsubaki&#x27;s enforcer — restrains Yagami in a Full Nelson then a headlock, apologizing but not relenting, threatening to retire him or extract Kushida&#x27;s secrets directly; his control of Class 1-C is revealed to be a front for Tsubaki&#x27;s manipulations.<span class=\"pg\">p.267–273<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsubaki Sakurako<\/b> Carries out her coercion — &quot;using Utomiya as a medium.&quot;<span class=\"pg\">p.272<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> Physically interrogates him.<span class=\"pg\">p.272–273<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-utomiya-riku-y2v4-p97-1","v":"y2v4","y":2,"o":19,"k":"","w":"utomiya-riku","q":"utomiya riku utomiya mentioned in passing  if it was one of the top ten  it was ryuuen s second year group  sakayanagi s group  or utomiya s group and the others in first year    narration   the only thing we should avoid is getting in the way of our efforts to eliminate ayanokouji senpai  and the only person capable of eliminating ayanokouji senpai  apart from utomiya kun  is housen kun    yagami","h":"<article class=\"card\" id=\"sc-utomiya-riku-y2v4-p97-1\"><h3><span class=\"ttl\">Utomiya mentioned in passing<\/span><span class=\"meta\">Y2V4 · p.97, 166<\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “if it was one of the top ten, it was Ryuuen&#x27;s second year group, Sakayanagi&#x27;s group, or Utomiya&#x27;s group and the others in first year.” — narration.<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “The only thing we should avoid is getting in the way of our efforts to eliminate Ayanokouji-senpai. And the only person capable of eliminating Ayanokouji-Senpai, apart from Utomiya-kun, is Housen-kun...” — Yagami.<span class=\"pg\">p.166<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-utomiya-riku-y2v4-p121-1\">→ After: Utomiya mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-utomiya-riku-y2v4-p121-1","v":"y2v4","y":2,"o":19,"k":"","w":"utomiya-riku","q":"utomiya riku utomiya mentioned in passing  housen was summoned by takahashi  yagami  tsubaki  and utomiya    nanase s report   i agree with you  because i had the impression that class c was more focused on utomiya    nanase   but utomiya and housen don t get along  and when it comes to arguing  they quickly get into quarrels  so tsubaki may have been deliberately chosen to act as an intermediary    nanase","h":"<article class=\"card\" id=\"sc-utomiya-riku-y2v4-p121-1\"><h3><span class=\"ttl\">Utomiya mentioned in passing<\/span><span class=\"meta\">Y2V4 · p.121<\/span><\/h3><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Housen was summoned by Takahashi, Yagami, Tsubaki, and Utomiya...” — Nanase&#x27;s report.<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I agree with you, because I had the impression that Class C was more focused on Utomiya.” — Nanase.<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “But Utomiya and Housen don&#x27;t get along, and when it comes to arguing, they quickly get into quarrels, so Tsubaki may have been deliberately chosen to act as an intermediary.” — Nanase.<span class=\"pg\">p.121<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-utomiya-riku-y2v4-p97-1\">← Before: Utomiya mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-utomiya-riku-y2v4-p128-1\">→ After: Ch.5: The negotiation; the scheme&#x27;s inside man<\/button><\/div><\/article>"},{"i":"sc-utomiya-riku-y2v4-p128-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"housen-kazuomi tsubaki-sakurako yagami-takuya utomiya-riku","q":"utomiya riku ch 5  the negotiation  the scheme s inside man utomiya  class 1 c s planner  sends katagiri with the walkie talkie to hosen  he negotiates over the radio from behind the line  he insists no one must touch katagiri    i didn t want to contact you  but i can t help but do it to carry out my plan   have you forgotten the sixth day   i took that fact into account   we should have a strategy to rescue the freshmen  1st year  soon   will you save the first years   wait a minute  no one said anything about not cooperating   what the hell is    i don t know what you re talking about  but what does it have to do with me   housen   i m not going to get any help from you  am i    do not be silly  who is going to bow down to you      are you saying you don t trust utomiya   it s true  some of them are already running out of food     i thought that making bad plays was pointless   there have been some students who have withdrawn so far this week  but so far there has been no group elimination  so it will be a difficult scenario for the rest of the week  and there could be an elimination of group somewhere   that s why we have a group of reserve tablets   wait  tsubaki  violence is forbidden as a general rule  would you act accordingly just to pay them 500 000      no  rather  i thought that making bad plays was pointless  i have been observing ayanokouji in my own way  and it is not just a coincidence that he has been the subject of 20 million  i think it s because it s clearly a rarity that he was the goal  even if you try to catch him within the rules  he will surely evade you  i have no right to stop you if you are willing to     what will we do   i m not sure what to think  but i m sure there s nothing wrong with following tsubaki s strategy  in any case  she intended to crush ayanokouji even if he was alone     we can do whatever we want  and the blame falls entirely on tsubaki  the ringleader  it s too good to be true     on the other hand  doesn t it seem suspicious that she sacrifices     well  it s welcome  anyway  that s it   what are you thinking  tsubaki    no  i just wanted to talk to you before the operation took place  it may be the last conversation with tsubaki so far     why didn t you use a walkie talkie to communicate with me   i guess so  i didn t even know what he was thinking  but i don t trust him at all     do you want to see the screenshot i took of one when i ran the gps search earlier   the arrangement is perfect  just as tsubaki planned   what happens   yesterday you suddenly disappeared  and where were you   in my case it was just a mistake   hey you two  could you please not get in trouble at a time like this  after all  we are friends  right     i too have stepped out of line and i apologize    a gift    of course  tsubaki s strategy is perfect  it s an alignment that leaves no room for ants to crawl out of bounds  we are challenging with the greatest strength that we can prepare freshmen  so i don t doubt our success  but don t you think it s better to take the preventive measures you can     we do not know where the designated area of ayanokouji senpai is  so we cannot predict his movements   you mean you know   how can you be sure that this tablet really is from the same box as ayanokouji   shouldn t he be there after all  i m sure i can go one on one with ayanokouji and win    that is enough for a normal opponent  but ayanokouji is a 20 million point opponent  so he is not an ordinary player  as long as housen made the first move  he could not gain an advantage  he must make the moves he can    he is the quiet chess master behind tsubaki s plan   he encourages the violence but keeps his own hands clean  he measures ayanokoji as a 20 million point opponent  he is the only first year tsubaki trusts  his partner in the plan  they stay in sync on paper  he sent the walkie talkie  warns tsubaki to leave katagiri alone  his class b ally  they treat each other as peers","h":"<article class=\"card\" id=\"sc-utomiya-riku-y2v4-p128-1\"><h3><span class=\"ttl\">Ch.5: The negotiation; the scheme&#x27;s inside man<\/span><span class=\"meta\">Y2V4 · p.128–149<\/span><\/h3><p class=\"setup\">Utomiya, Class 1-C&#x27;s planner, sends Katagiri with the walkie-talkie to Hōsen; he negotiates over the radio from behind the line; he insists no one must touch Katagiri.<\/p><p class=\"with\">with <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"tsubaki-sakurako.html\">Tsubaki Sakurako<\/a> · <a href=\"yagami-takuya.html\">Yagami Takuya<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“... I didn&#x27;t want to contact you. But I can&#x27;t help but do it to carry out my plan.”<span class=\"pg\">p.129<\/span><\/li><li class=\"q spoken\">“Have you forgotten the sixth day?”<span class=\"pg\">p.130<\/span><\/li><li class=\"q spoken\">“I took that fact into account”<span class=\"pg\">p.130<\/span><\/li><\/ul><details class=\"more\"><summary>42 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “We should have a strategy to rescue the freshmen (1st year) soon.”<span class=\"pg\">p.130<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Will you save the first years?”<span class=\"pg\">p.130<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wait a minute. No one said anything about not cooperating.”<span class=\"pg\">p.130<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What the hell is ......?”<span class=\"pg\">p.130<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t know what you&#x27;re talking about, but what does it have to do with me?”<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Housen”.<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m not going to get any help from you, am I?”<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “ Do not be silly. Who is going to bow down to you? ”<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “ Are you saying you don&#x27;t trust Utomiya?”<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s true. Some of them are already running out of food. ”<span class=\"pg\">p.134<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…I thought that making bad plays was pointless...”<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There have been some students who have withdrawn so far this week, but so far there has been no group elimination, so it will be a difficult scenario for the rest of the week, and there could be an elimination of group somewhere.”<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s why we have a group of reserve tablets.”<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wait, Tsubaki, Violence is forbidden as a general rule, would you act accordingly just to pay them 500,000? ”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…… No. Rather, I thought that making bad plays was pointless... I have been observing Ayanokouji in my own way, and it is not just a coincidence that he has been the subject of 20 million. I think it&#x27;s because it&#x27;s clearly a rarity that he was the goal. Even if you try to catch him within the rules, he will surely evade you. I have no right to stop you if you are willing to. ”<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What will we do?”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m not sure what to think, but I&#x27;m sure there&#x27;s nothing wrong with following Tsubaki&#x27;s strategy. In any case, she intended to crush Ayanokouji even if he was alone. ”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We can do whatever we want, and the blame falls entirely on Tsubaki, the ringleader. It&#x27;s too good to be true. ”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “On the other hand, doesn&#x27;t it seem suspicious that she sacrifices…... ?”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, it&#x27;s welcome. Anyway, that&#x27;s it.”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What are you thinking? Tsubaki”<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “ No, I just wanted to talk to you before the operation took place. It may be the last conversation with Tsubaki so far. ”<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Why didn&#x27;t you use a walkie-talkie to communicate with me?”<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I guess so. I didn&#x27;t even know what he was thinking, but I don&#x27;t trust him at all. ”<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you want to see the screenshot I took of one when I ran the GPS search earlier?”<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The arrangement is perfect, just as Tsubaki planned.”<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What happens?.”<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yesterday you suddenly disappeared, and where were you?”<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In my case it was just a mistake.”<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hey you two, could you please not get in trouble at a time like this? After all, we are friends, right? ”<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I too have stepped out of line and I apologize.”<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “ A gift?”<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “ Of course, Tsubaki&#x27;s strategy is perfect. It&#x27;s an alignment that leaves no room for ants to crawl out of bounds. We are challenging with the greatest strength that we can prepare freshmen. So I don&#x27;t doubt our success. But don&#x27;t you think it&#x27;s better to take the preventive measures you can? ”<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We do not know where the designated area of Ayanokouji-senpai is, so we cannot predict his movements.”<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You mean you know?”<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How can you be sure that this tablet really is from the same box as Ayanokouji?”<span class=\"pg\">p.144<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Shouldn&#x27;t he be there after all? I&#x27;m sure I can go one-on-one with Ayanokouji and win.”<span class=\"pg\">p.148<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “ That is enough for a normal opponent. But Ayanokouji is a 20 million point opponent, so he is not an ordinary player. As long as Housen made the first move, he could not gain an advantage, he must make the moves he can. ”<span class=\"pg\">p.148<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He is the quiet chess master behind Tsubaki&#x27;s plan — he encourages the violence but keeps his own hands clean; he measures Ayanokōji as a 20-million-point opponent; he is the only first-year Tsubaki trusts.<span class=\"pg\">p.128–149<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsubaki Sakurako<\/b> His partner in the plan; they stay in sync on paper.<span class=\"pg\">p.128–149<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> He sent the walkie-talkie; warns Tsubaki to leave Katagiri alone.<span class=\"pg\">p.128–133<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> His Class B ally; they treat each other as peers.<span class=\"pg\">p.141–149<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-utomiya-riku-y2v4-p121-1\">← Before: Utomiya mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-utomiya-riku-y2v4-p151-1\">→ After: Ch.5: The collapse; the walkie-talkie lost<\/button><\/div><\/article>"},{"i":"sc-utomiya-riku-y2v4-p151-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"tsubaki-sakurako yagami-takuya utomiya-riku","q":"utomiya riku ch 5  the collapse  the walkie talkie lost he is sent to hold position with the five frozen groups  the plan collapses  he drops the walkie talkie after kitou stops him  tsubaki is forced to abandon the island   it s true  but    what  did you say something   if so  i cannot accept the reward  i reject the 5 million points  then i ll be watching from a distance     not a bad idea  don t you think  tsubaki   hmm  not exactly  it is correct to say that we decided to carry out this operation because we were absolutely sure that housen kun would come on board  it seems that he was always willing to fight alone  still  if they didn t accept the case  i would just let utomiya kun go  either way  i made sure the atmosphere was perfect for one on one  now it only remains for the two to face each other  win or lose  and everything will be fine   what are you doing   what do you want on these roads   i m not going to let you pass from here   i ll tell you  i m not going to let you pass from here   didn t you follow my instructions   the objective has been reached   he went right in front of me    i ve gotten rid of that 2nd year weirdo  i should be pleased to see that tsubaki is in charge   so  how was tsubaki s plan   it failed as expected  even though ayanokouji senpai didn t bother to give advance notice  i m sure it was an old fashioned strategy that was never going to be successful from the beginning   i have to go  without inadvertently prolonging the matter  utomiya turns off the walkie talkie  very good  his walkie talkie is lost to kitou  she knows her plan has failed","h":"<article class=\"card\" id=\"sc-utomiya-riku-y2v4-p151-1\"><h3><span class=\"ttl\">Ch.5: The collapse; the walkie-talkie lost<\/span><span class=\"meta\">Y2V4 · p.151–190<\/span><\/h3><p class=\"setup\">He is sent to hold position with the five frozen groups; the plan collapses; he drops the walkie-talkie after Kitou stops him; Tsubaki is forced to abandon the island.<\/p><p class=\"with\">with <a href=\"tsubaki-sakurako.html\">Tsubaki Sakurako<\/a> · <a href=\"yagami-takuya.html\">Yagami Takuya<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“It&#x27;s true, but ......”<span class=\"pg\">p.155<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsubaki Sakurako<\/b> “What, did you say something?”<span class=\"pg\">p.158<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Yagami Takuya<\/b> “If so, I cannot accept the reward, I reject the 5 million points. Then I&#x27;ll be watching from a distance. ”<span class=\"pg\">p.160<\/span><\/li><\/ul><details class=\"more\"><summary>15 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Not a bad idea, don&#x27;t you think, Tsubaki?”<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hmm, not exactly. It is correct to say that we decided to carry out this operation because we were absolutely sure that Housen-kun would come on board. It seems that he was always willing to fight alone. Still, if they didn&#x27;t accept the case, I would just let Utomiya-kun go. Either way, I made sure the atmosphere was perfect for one-on-one. Now it only remains for the two to face each other, win or lose, and everything will be fine.”<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What are you doing……?”<span class=\"pg\">p.185<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What do you want on these roads?”<span class=\"pg\">p.186<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m not going to let you pass from here.”<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;ll tell you. I&#x27;m not going to let you pass from here.”<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Didn&#x27;t you follow my instructions?”<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “.....The objective has been reached”<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “He went right in front of me ..”<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;ve gotten rid of that 2nd year weirdo. I should be pleased to see that Tsubaki is in charge.”<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So, how was Tsubaki&#x27;s plan?”<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It failed as expected. Even though Ayanokouji-senpai didn&#x27;t bother to give advance notice, I&#x27;m sure it was an old-fashioned strategy that was never going to be successful from the beginning.”<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have to go.” Without inadvertently prolonging the matter, Utomiya turns off the walkie-talkie<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Very good.”<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsubaki Sakurako<\/b> His walkie-talkie is lost to Kitou; she knows her plan has failed.<span class=\"pg\">p.185–190<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-utomiya-riku-y2v4-p128-1\">← Before: Ch.5: The negotiation; the scheme&#x27;s inside man<\/button><\/div><\/article>"},{"i":"sc-utomiya-riku-y2v4_5-p10-1","v":"y2v4.5","y":2,"o":20,"k":"","w":"kurachi nanase-tsubasa ryuuen-kakeru utomiya-riku","q":"utomiya riku relations in this volume  depth pass  kurachi fingers him as the planner  he never appears on page  she confronts his tent plan  he s not there  ryuen wants to hunt him  she stalls him","h":"<article class=\"card\" id=\"sc-utomiya-riku-y2v4_5-p10-1\"><h3><span class=\"ttl\">Relations in this volume (depth pass)<\/span><span class=\"meta\">Y2V4.5 · p.10–290<\/span><\/h3><p class=\"with\">with <a href=\"index.html#kurachi\">Kurachi<\/a> · <a href=\"nanase-tsubasa.html\">Nanase Tsubasa<\/a> · <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kurachi<\/b> Kurachi fingers him as the planner; he never appears on-page.<span class=\"pg\">p.189–191<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> She confronts his tent-plan; he&#x27;s not there.<span class=\"pg\">p.189–190<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Ryūen wants to hunt him; she stalls him.<span class=\"pg\">p.190<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-utomiya-riku-y2v4_5-p189-1\">→ After: Utomiya named by Kurachi: the moneyed assailant<\/button><\/div><\/article>"},{"i":"sc-utomiya-riku-y2v4_5-p189-1","v":"y2v4.5","y":2,"o":20,"k":"","w":"utomiya-riku","q":"utomiya riku utomiya named by kurachi  the moneyed assailant kurachi identifies him   it was my classmate  utomiya   kurachi  p 189    utomiya has no lines of his own in this volume  kurachi fingers utomiya riku  first year class c  as the one who promised money for the  attack  on ayanokoji  kurachi claims the money was transferred without him doing anything  ryuen pulls up utomiya s oaa  an a in physical ability  wonders aloud if he could have pushed komiya without komiya realizing  decides  i m gonna hunt down this utomiya brat and get him to talk  nanase stops him   if utomiya kun is the culprit  if it was decided he was innocent  that would be the end of it  wouldn t it    she asks for time and gets it  on the condition that ryuen holds off contacting utomiya  nanase claims utomiya  might  be physically capable  leaves it at that  no contact yet","h":"<article class=\"card\" id=\"sc-utomiya-riku-y2v4_5-p189-1\"><h3><span class=\"ttl\">Utomiya named by Kurachi: the moneyed assailant<\/span><span class=\"meta\">Y2V4.5 · p.189–191<\/span><\/h3><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Kurachi identifies him: “It was my classmate, Utomiya.” (Kurachi, p.189) — Utomiya has no lines of his own in this volume.<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Kurachi fingers Utomiya Riku, first-year Class C, as the one who promised money for the &quot;attack&quot; on Ayanokōji; Kurachi claims the money was transferred without him doing anything.<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ryūen pulls up Utomiya&#x27;s OAA: an A in physical ability; wonders aloud if he could have pushed Komiya without Komiya realizing; decides &quot;I&#x27;m gonna hunt down this Utomiya brat and get him to talk.&quot;<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Nanase stops him: &quot;If Utomiya-kun is the culprit, if it was decided he was innocent, that would be the end of it, wouldn&#x27;t it?&quot; — she asks for time and gets it, on the condition that Ryūen holds off contacting Utomiya.<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Nanase claims Utomiya &quot;might&quot; be physically capable; leaves it at that; no contact yet.<span class=\"pg\">p.191<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-utomiya-riku-y2v4_5-p10-1\">← Before: Relations in this volume (depth pass)<\/button><\/div><\/article>"},{"i":"sc-utomiya-riku-y2v7-p191-1","v":"y2v7","y":2,"o":23,"k":"","w":"ayanokouji-kiyotaka utomiya-riku","q":"utomiya riku tsubaki sakurako s white room play  2   after the festival ends  utomiya waits outside the school with tsubaki  ak receives a phone call from an unknown number at the classroom  the voice sounds familiar   tsubaki sakurako  a student in first year class c  the caller   are you still in school  i d like to talk to you for a minute if you d like  ayanokoji   are you alone now    the caller   unfortunately not    the caller   then why don t we meet up    ayanokoji   where are you    the caller   i just left the front door  you re still on campus  right    ayanokoji   give me five minutes    the caller   okay  tsubaki  making a circle with her finger as if to say   you passed  tells him she is very grateful ayanokoji senpai successfully extracted information from sato senpai and drove yagami kun out of school  utomiya was with tsubaki at the meeting  utomiya was talking to someone a little farther away  he was only looking at them   well  the first year students are in a bit of a mess right now  there was an unexpected expulsion at the school festival    tsubaki  the person in front of him is tsubaki sakurako   i m satisfied with the result  which is more than i imagined ayanokoji senpai  sato was apparently approached by tsubaki near the women s restroom at keyaki mall  there  she flashed some bait that would turn things around for her  including a turnaround between his relationship with kei  which tickled her curiosity  she intensified the threats gradually over days because sato would eventually come to consult someone  and that would be ayanokoji   as soon as you saw that sato wouldn t accept your invitation  you contacted her again as if to follow up and made similar comments and provoked her  when you saw that sato didn t seem to have consulted anyone  you gradually intensified your threats and hounded her  this was due to the fact that she would eventually come to consult someone  and that would be me    ayanokoji s read of the three week squeeze  the man on the phone   yagami had some of tsubaki s and utomiya s classmates expelled  that s why those two worked together with me   go ahead    wary  utomiya handed the phone to ayanokoji while it was still connected   utomiya kun  can you come here for a minute    tsubaki beckoned to utomiya and instructed him to hand his cell phone to ayanokoji  the only people who know about karuizawa s past are those who are connected with the white room  others can t easily imitate him   senpai    utomiya  who was forcing himself to pull out the honorific  returned to the dormitory with tsubaki  he is with her at the meeting  he hands his phone over   senpai  she works with him against yagami  she reports the expulsion  she leaves the school","h":"<article class=\"card\" id=\"sc-utomiya-riku-y2v7-p191-1\"><h3><span class=\"ttl\">Tsubaki Sakurako&#x27;s White Room play<\/span><span class=\"meta\">Y2V7 · p.191–199<\/span><\/h3><p class=\"setup\">§2 — after the festival ends; Utomiya waits outside the school with Tsubaki; AK receives a phone call from an unknown number at the classroom; the voice sounds familiar — Tsubaki Sakurako, a student in first-year Class C.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>14 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The caller: “Are you still in school? I&#x27;d like to talk to you for a minute if you&#x27;d like.”<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji: “Are you alone now?” — the caller: “Unfortunately not.” — the caller: “Then why don&#x27;t we meet up?” — Ayanokōji: “Where are you?” — the caller: “I just left the front door. You&#x27;re still on campus, right?” — Ayanokōji: “Give me five minutes.” — the caller: “Okay.”<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsubaki, making a circle with her finger as if to say, “you passed,” tells him she is very grateful Ayanokōji-senpai successfully extracted information from Satō-senpai and drove Yagami-kun out of school.<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Utomiya was with Tsubaki at the meeting; Utomiya was talking to someone a little farther away; he was only looking at them.<span class=\"pg\">p.192–193<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Well, the first-year students are in a bit of a mess right now. There was an unexpected expulsion at the school festival.” — Tsubaki; the person in front of him is Tsubaki Sakurako; “I&#x27;m satisfied with the result, which is more than I imagined…Ayanokōji-senpai.”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Satō was apparently approached by Tsubaki near the women&#x27;s restroom at Keyaki Mall; there, she flashed some bait that would turn things around for her, including a turnaround between his relationship with Kei, which tickled her curiosity; she intensified the threats gradually over days because Satō would eventually come to consult someone, and that would be Ayanokōji.<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “As soon as you saw that Satō wouldn&#x27;t accept your invitation, you contacted her again as if to follow up and made similar comments and provoked her. When you saw that Satō didn&#x27;t seem to have consulted anyone, you gradually intensified your threats and hounded her. This was due to the fact that she would eventually come to consult someone, and that would be me.” — Ayanokōji&#x27;s read of the three-week squeeze.<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The man on the phone: “Yagami had some of Tsubaki&#x27;s and Utomiya&#x27;s classmates expelled. That&#x27;s why those two worked together with me.”<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Go ahead...” — Wary, Utomiya handed the phone to Ayanokōji while it was still connected.<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Utomiya-kun, can you come here for a minute?” — Tsubaki beckoned to Utomiya and instructed him to hand his cell phone to Ayanokōji.<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The only people who know about Karuizawa&#x27;s past are those who are connected with the White Room; others can&#x27;t easily imitate him.<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Senpai.” — Utomiya, who was forcing himself to pull out the honorific, returned to the dormitory with Tsubaki.<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> He is with her at the meeting; he hands his phone over; “Senpai.”<span class=\"pg\">p.191–199<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She works with him against Yagami; she reports the expulsion; she leaves the school.<span class=\"pg\">p.191–199<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-utomiya-riku-y2v11-p130-1","v":"y2v11","y":2,"o":30,"k":"spoken","w":"ryuuen-kakeru housen-kazuomi utomiya-riku","q":"utomiya riku ch 5  the mediator nobody asked for he catches the commotion  talks straight into ryuen  the third years gather   excuse me  but could you let go of your hand  ryuen senpai   i came to see if you were going to raise your hand against senpai   tokito senpai is a member of my group  if he gets injured here  it could have an effect tomorrow  no matter how much it s an in class issue  i can t overlook it   the problem is the guy who s using his position to threaten others at this shitty exchange meeting   are you okay with that  you ll be embarrassed in front of your friends as a senpai   shut up  hosen  i don t need you  don t cause unnecessary trouble   even if i talk to a big gorilla  words won t get through   no  it s not  we were just having a light hearted conversation  he stands for tokito  he ignores hosen  he disguises the fight as a chat when the third years appear  ryuen barely notes him  he faces ryuen down  ryuen asks him to leave at the end  he lets the scene close  he treats him like ryuen  hosen erupts","h":"<article class=\"card\" id=\"sc-utomiya-riku-y2v11-p130-1\"><h3><span class=\"ttl\">Ch.5: The mediator nobody asked for<\/span><span class=\"meta\">Y2V11 · p.130–132<\/span><\/h3><p class=\"setup\">He catches the commotion; talks straight into Ryūen; the third-years gather.<\/p><p class=\"with\">with <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Excuse me, but could you let go of your hand, Ryūen-senpai?”<span class=\"pg\">p.130<\/span><\/li><li class=\"q spoken\">“I came to see if you were going to raise your hand against Senpai.”<span class=\"pg\">p.130<\/span><\/li><li class=\"q spoken\">“Tokitō-senpai is a member of my group. If he gets injured here, it could have an effect tomorrow. No matter how much it&#x27;s an in-class issue, I can&#x27;t overlook it.”<span class=\"pg\">p.130<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “...The problem is the guy who&#x27;s using his position to threaten others at this shitty exchange meeting...”<span class=\"pg\">p.130<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you okay with that? You&#x27;ll be embarrassed in front of your friends as a senpai.”<span class=\"pg\">p.130<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Shut up, Hōsen. I don&#x27;t need you. Don&#x27;t cause unnecessary trouble.”<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even if I talk to a big gorilla, words won&#x27;t get through.”<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, it&#x27;s not. We were just having a light-hearted conversation.”<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> He stands for Tokitō; he ignores Hōsen; he disguises the fight as a chat when the third-years appear; Ryūen barely notes him.<span class=\"pg\">p.130–132<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> He faces Ryūen down; Ryūen asks him to leave at the end; he lets the scene close.<span class=\"pg\">p.130–132<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> He treats him like Ryūen; Hōsen erupts.<span class=\"pg\">p.131<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-utomiya-riku-y2v11-p174-1\">→ After: Ch.7: The witness&#x27;s account<\/button><\/div><\/article>"},{"i":"sc-utomiya-riku-y2v11-p174-1","v":"y2v11","y":2,"o":30,"k":"","w":"utomiya-riku","q":"utomiya riku ch 7  the witness s account yamamura s account to kiyotaka   however  tokito s groupmates  hosen and utomiya  joined in  and there was a risk of a brawl  it seemed that the situation was resolved when the number of students who heard the commotion suddenly increased all at once  and they dispersed    the witness s account of his joining  named as one of the groupmates who joined  not present on these pages","h":"<article class=\"card\" id=\"sc-utomiya-riku-y2v11-p174-1\"><h3><span class=\"ttl\">Ch.7: The witness&#x27;s account<\/span><span class=\"meta\">Y2V11 · p.174<\/span><\/h3><p class=\"setup\">Yamamura&#x27;s account to Kiyotaka.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “However, Tokitō&#x27;s groupmates, Hōsen and Utomiya, joined in, and there was a risk of a brawl. It seemed that the situation was resolved when the number of students who heard the commotion suddenly increased all at once, and they dispersed.” — the witness&#x27;s account of his joining.<span class=\"pg\">p.174<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Named as one of the groupmates who joined; not present on these pages.<span class=\"pg\">p.174<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-utomiya-riku-y2v11-p130-1\">← Before: Ch.5: The mediator nobody asked for<\/button><\/div><\/article>"},{"i":"sc-utomiya-riku-y2v12-p12-1","v":"y2v12","y":2,"o":31,"k":"","w":"utomiya-riku","q":"utomiya riku utomiya riku mentioned in passing named in this volume  passing mention  locator pages  p 28  not line by line verified  substring false positives possible  not a scene presence  passing mention only","h":"<article class=\"card\" id=\"sc-utomiya-riku-y2v12-p12-1\"><h3><span class=\"ttl\">utomiya-riku mentioned in passing<\/span><span class=\"meta\">Y2V12 · p.12-228<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention (locator pages: p.28; not line-by-line verified; substring false positives possible). Not a scene presence.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.12<\/span><\/li><\/ul><\/details><\/article>"}];
